/**
 * Generates OpenCode's event bridge for one plugin's hooks.json. OpenCode's loader scans no
 * "hooks" family and this profile writes no hooks.json, so without this module a plugin's
 * declared hooks have no trigger on OpenCode at all. The generated file is a real OpenCode
 * plugin with V1/server and V2/setup entrypoints, spawning the scripts every host's hooks.json
 * already names over the stdin-JSON contract those scripts already read.
 *
 * Only three hook events are replayed:
 *
 * - Unmatched `SessionStart` runs once per server/directory at initialization and requires
 *   idempotent commands. Hooks matching `startup` run for each delivered session.created.
 *   V1 did not always deliver this event; V2 does.
 * - `Stop` maps to V1's `session.idle` or V2's execution terminal, once per turn.
 * - `PostToolUse` maps to V1's `tool.execute.after`, the one hook that waits for the script and
 *   can append its exit-2 stderr to the tool's output, which is how a problem reaches the model.
 *   V2's adapter calls the same hook from a successful tool call, without that answer.
 *
 * A `matcher` on a `PostToolUse` group filters by tool name, exact or pipe-separated
 * alternation, ignoring case: OpenCode names its tools in lowercase. Absent, every tool matches.
 */

interface ParsedHookCall {
  readonly script: string;
  readonly args: readonly string[];
}

interface ParsedPostToolUseCall extends ParsedHookCall {
  readonly matcher?: string;
}

interface OpencodeHookTable {
  readonly sessionStart: readonly ParsedHookCall[];
  readonly stop: readonly ParsedHookCall[];
  readonly postToolUse: readonly ParsedPostToolUseCall[];
}

interface ClaudeHookItem {
  readonly type?: string;
  readonly command?: string;
}

interface ClaudeMatcherGroup {
  readonly matcher?: string;
  readonly hooks?: readonly ClaudeHookItem[];
}

interface ClaudeHooksShape {
  readonly hooks?: Record<string, readonly ClaudeMatcherGroup[]>;
}

// Read replayable commands from the canonical Claude-format manifest.
const COMMAND_PATTERN =
  /^node\s+(?:"\$\{CLAUDE_PLUGIN_ROOT\}\/hooks\/([^"]+)"|\$\{CLAUDE_PLUGIN_ROOT\}\/hooks\/(\S+))(.*)$/;

function parseCommand(command: string | undefined): ParsedHookCall | null {
  if (typeof command !== "string") return null;
  const match = COMMAND_PATTERN.exec(command.trim());
  if (!match) return null;
  const [, quotedScript, bareScript, rest] = match;
  const script = quotedScript ?? bareScript;
  const args = rest.trim().length > 0 ? rest.trim().split(/\s+/) : [];
  return { script, args };
}

function parseGroups(groups: readonly ClaudeMatcherGroup[] | undefined): ParsedPostToolUseCall[] {
  const calls: ParsedPostToolUseCall[] = [];
  for (const group of groups ?? []) {
    for (const item of group.hooks ?? []) {
      const parsed = parseCommand(item.command);
      if (parsed === null) continue;
      calls.push(group.matcher ? { ...parsed, matcher: group.matcher } : parsed);
    }
  }
  return calls;
}

/** Read source hooks; the generated bridge resolves scripts beside itself. */
export function parseHooksJsonForBridge(rawHooksJson: string): OpencodeHookTable {
  const parsed = JSON.parse(rawHooksJson) as ClaudeHooksShape;
  const hooks = parsed.hooks ?? {};
  return {
    sessionStart: parseGroups(hooks.SessionStart),
    stop: parseGroups(hooks.Stop),
    postToolUse: parseGroups(hooks.PostToolUse),
  };
}

// Every plugin this generator sees is already named "aidd-<something>", so an "Aidd" prefix
// here would stutter rather than name anything the plugin's own PascalCased name does not.
function toIdentifier(plugin: string): string {
  const pascal = plugin
    .split("-")
    .filter(Boolean)
    .map((part) => part[0]?.toUpperCase() + part.slice(1))
    .join("");
  return `${pascal}Hooks`;
}

function callTableLiteral(calls: readonly ParsedHookCall[]): string {
  return JSON.stringify(calls);
}

/** A plugin's raw hooks.json + its name -> the full text of its generated OpenCode bridge
 * module, or `null` when none of the three mapped events named anything replayable — a bridge
 * with nothing to spawn is not a file worth writing. */
export function generateOpencodeHooksBridge(rawHooksJson: string, plugin: string): string | null {
  const table = parseHooksJsonForBridge(rawHooksJson);
  if (
    table.sessionStart.length === 0 &&
    table.stop.length === 0 &&
    table.postToolUse.length === 0
  ) {
    return null;
  }
  const ident = toIdentifier(plugin);
  return `// Generated by aidd from plugins/${plugin}/hooks/hooks.json - do not edit by hand.
// OpenCode's plugin loader scans no "hooks" family and this profile writes no hooks.json
// (build.ts's skipHooksJson, translated here rather than skipped) - this file is the only
// trigger this plugin's declared hooks have on OpenCode. See opencode-hooks-bridge.ts for
// the mapping this generator applies and the measurements behind it.
import { setupOpencodeEvents } from "../hooks/opencode-events.js";
import { spawn } from "node:child_process";
import { existsSync } from "node:fs";
import { fileURLToPath } from "node:url";

// Never process.execPath: OpenCode ships as its own standalone binary - that path names \`opencode\`
// itself, not a Node runtime able to run this plugin's own hook scripts.
const HOOKS_DIR = fileURLToPath(new URL("../hooks/${plugin}/", import.meta.url));

const SESSION_START = ${callTableLiteral(table.sessionStart)};
const STOP = ${callTableLiteral(table.stop)};
const POST_TOOL_USE = ${callTableLiteral(table.postToolUse)};

// Asynchronous on purpose: this can spawn one script per matching hook across every mapped
// event, and blocking OpenCode's event loop once per hook would multiply the cost. A failed spawn (ENOENT, a killed timeout)
// must not throw past this function - both listeners below, plus the caller's own
// try/catch, exist because a spawn that never launches can still throw on the stdin write.
function runHook(script, args, payload, directory) {
  const child = spawn("node", [HOOKS_DIR + script, ...args], {
    cwd: directory,
    stdio: ["pipe", "ignore", "ignore"],
    timeout: 5000,
  });
  child.on("error", () => {});
  child.stdin.on("error", () => {});
  child.stdin.end(JSON.stringify(payload));
}

/** Pure: \`session.idle\` -> every Stop hook's own {script, args, payload} - or \`[]\` for
 * any other event. Exported as a property (never a second named export - F6) so this
 * generated module's own mapping can be asserted without spawning anything. */
function stopCallsFor(event, directory) {
  if (event?.type !== "session.idle") return [];
  const sessionId = event.properties?.sessionID;
  return STOP.map((hook) => ({
    script: hook.script,
    args: hook.args,
    payload: { hook_event_name: "Stop", session_id: sessionId ?? null, cwd: directory },
  }));
}

// Awaited, unlike runHook: the script has something the model must read.
// Exit 2 puts it on stderr; exit 0 puts it in additionalContext on stdout.
function answerFrom(code, stdout, stderr) {
  if (code === 2) return stderr.trim();
  if (code !== 0) return "";
  try {
    const output = JSON.parse(stdout);
    return String(output?.hookSpecificOutput?.additionalContext ?? output?.additionalContext ?? "").trim();
  } catch {
    return "";
  }
}

/** Runs one hook script with its payload on stdin and collects what it wrote. */
function runCapture(script, args, payload, directory) {
  return new Promise((resolve) => {
    let stdout = "";
    let stderr = "";
    const child = spawn("node", [HOOKS_DIR + script, ...args], {
      cwd: directory,
      stdio: ["pipe", "pipe", "pipe"],
      timeout: 5000,
    });
    child.stdout.on("data", (chunk) => {
      stdout += chunk;
    });
    child.stderr.on("data", (chunk) => {
      stderr += chunk;
    });
    child.on("error", () => resolve({ code: null, stdout: "", stderr: "" }));
    child.on("close", (code) => resolve({ code, stdout, stderr }));
    child.stdin.on("error", () => {});
    child.stdin.end(JSON.stringify(payload));
  });
}

function answerOf(script, args, payload, directory) {
  return runCapture(script, args, payload, directory).then(({ code, stdout, stderr }) =>
    answerFrom(code, stdout, stderr)
  );
}

/** A Stop script's {"decision":"block","reason"} on stdout: the reason to keep working on. */
function stopReasonOf(script, args, payload, directory) {
  return runCapture(script, args, payload, directory).then(({ code, stdout }) => {
    if (code !== 0) return "";
    try {
      const output = JSON.parse(stdout);
      return output?.decision === "block" ? String(output.reason ?? "").trim() : "";
    } catch {
      return "";
    }
  });
}

/** Pure: a finished tool call -> every PostToolUse hook whose matcher allows its tool. OpenCode
 * names the written file \`filePath\`; the scripts read Claude Code's \`file_path\`. */
function postToolUseCallsFor(call, directory) {
  const tool = String(call?.tool ?? "");
  const args = call?.args;
  const matches = (matcher) =>
    !matcher || matcher.split("|").some((name) => name.toLowerCase() === tool.toLowerCase());
  const toolInput = typeof args?.filePath === "string" ? { ...args, file_path: args.filePath } : args;
  return POST_TOOL_USE.filter((hook) => matches(hook.matcher)).map((hook) => ({
    script: hook.script,
    args: hook.args,
    payload: {
      hook_event_name: "PostToolUse",
      session_id: call?.sessionID ?? null,
      cwd: directory,
      tool_name: tool,
      tool_input: toolInput,
    },
  }));
}

export const ${ident} = async (input) => {
  // Sessions whose last Stop asked the model to continue: their next Stop carries stop_hook_active.
  const continued = new Set();
  const started = new Set();
  // Existing unmatched hooks are intentionally still run at initialization.
  try {
    for (const hook of SESSION_START.filter((hook) => hook.matcher !== "startup")) {
      runHook(
        hook.script,
        hook.args,
        { hook_event_name: "SessionStart", session_id: null, cwd: input.directory },
        input.directory
      );
    }
  } catch {
    // Silent on purpose - see above.
  }
  return {
    event: async ({ event }) => {
      try {
        const directory = event?.properties?.info?.directory ?? event?.properties?.directory ?? input.directory;
        const id = event?.properties?.sessionID ?? event?.properties?.info?.id;
        if (event?.type === "session.deleted") started.delete(id);
        if (!input.skipStartup && event?.type === "session.created" && typeof id === "string" && !started.has(id)) {
          started.add(id);
          for (const hook of SESSION_START.filter((hook) => hook.matcher === "startup")) {
            const { code, stdout } = await runCapture(hook.script, hook.args,
              { hook_event_name: "SessionStart", session_id: id, cwd: directory, tool: "opencode" }, directory);
            let message = "";
            if (code === 0) {
              try { message = String(JSON.parse(stdout)?.systemMessage ?? "").trim(); } catch { message = ""; }
            }
            if (message && typeof input.client?.tui?.showToast === "function") {
              await input.client.tui.showToast({ body: { message, variant: "info" } });
            } else if (message) {
              console.warn("[aidd] OpenCode cannot display the startup message: " + message);
            }
          }
        }
        for (const call of stopCallsFor(event, directory)) {
          const sessionId = call.payload.session_id;
          const payload = { ...call.payload, stop_hook_active: continued.has(sessionId) };
          const reason = await stopReasonOf(call.script, call.args, payload, directory);
          if (!reason) {
            continued.delete(sessionId);
            continue;
          }
          continued.add(sessionId);
          // Not awaited: the prompt is the session's next turn, and this handler must not hold it.
          input.client.session
            .promptAsync({ path: { id: sessionId }, body: { parts: [{ type: "text", text: reason }] } })
            .catch(() => {});
        }
      } catch {
        // Silent on purpose - see above.
      }
    },
    "tool.execute.after": async (call, output) => {
      try {
        for (const hook of postToolUseCallsFor(call, input.directory)) {
          const answer = await answerOf(hook.script, hook.args, hook.payload, input.directory);
          if (answer) output.output = \`\${output.output ?? ""}\\n\\n\${answer}\`;
        }
      } catch {
        // Silent on purpose - see above.
      }
    },
  };
};

${ident}.stopCallsFor = stopCallsFor;
${ident}.postToolUseCallsFor = postToolUseCallsFor;

export default {
  id: ${JSON.stringify(`${plugin}-hooks`)},
  server: ${ident},
  setup: (ctx) => setupOpencodeEvents(ctx, (input) => ${ident}({
    ...input,
    skipStartup: existsSync(fileURLToPath(new URL("../plugins/${plugin}-tui/tui.js", import.meta.url))),
  })),
};
`;
}
